import { $, EChart, type EChartSetup } from "@/components/ui/echart"
import * as echarts from "echarts"
import type { EChartsOption } from "echarts"

const ROOT_PATH = "https://cdn.jsdelivr.net/gh/apache/echarts-examples@88ca004030e999073a15303e5fe32462b8fefae2/public"

// Adapted from the Apache ECharts example "Mix Zoom On Value" (Apache-2.0):
// https://echarts.apache.org/examples/en/editor.html?c=mix-zoom-on-value
const setup: EChartSetup = ({ myChart }) => {
  let option!: EChartsOption
  myChart.showLoading();

  $.get(
    ROOT_PATH + '/data/asset/data/obama_budget_proposal_2012.list.json',
    function (obama_budget_2012) {
      myChart.hideLoading();

      option = {
        tooltip: {
          trigger: 'axis',
          axisPointer: {
            type: 'shadow',
            label: {
              show: true
            }
          }
        },
        toolbox: {
          show: true,
          feature: {
            mark: { show: true },
            dataView: { show: true, readOnly: false },
            magicType: { show: true, type: ['line', 'bar'] },
            restore: { show: true },
            saveAsImage: { show: true }
          }
        },
        calculable: true,
        legend: {
          data: ['Growth', 'Budget 2011', 'Budget 2012'],
          itemGap: 5
        },
        grid: {
          top: '12%',
          left: '1%',
          right: '10%',
          containLabel: true
        },
        xAxis: [
          {
            type: 'category',
            data: obama_budget_2012.names
          }
        ],
        yAxis: [
          {
            type: 'value',
            name: 'Budget (million USD)',
            axisLabel: {
              formatter: function (a: number) {
                a = +a;
                return isFinite(a) ? echarts.format.addCommas(+a / 1000) : '';
              }
            }
          }
        ],
        dataZoom: [
          {
            show: true,
            start: 94,
            end: 100
          },
          {
            type: 'inside',
            start: 94,
            end: 100
          },
          {
            show: true,
            yAxisIndex: 0,
            filterMode: 'empty',
            width: 30,
            height: '80%',
            showDataShadow: false,
            left: '93%'
          }
        ],
        series: [
          {
            name: 'Budget 2011',
            type: 'bar',
            data: obama_budget_2012.budget2011List
          },
          {
            name: 'Budget 2012',
            type: 'bar',
            data: obama_budget_2012.budget2012List
          }
        ]
      };

      myChart.setOption(option);
    }
  );
  return option
}

export function EchartsMixZoomOnValue() {
  return <EChart setup={setup} />
}
